"""Second batch of supplementary questions for Class 10 Social Science Ch1 chapters.
Targets gaps: Civics + Economics objective; subjective across all four.
"""

from sqlalchemy import select
from app.db.session import SessionLocal
from app.models.curriculum import BloomLevel, LearningOutcome
from app.models.question import Question, QuestionDifficulty, QuestionStatus, QuestionType

CREATED_BY_ID = 14


def _options(q):
    return {"choices": list(q["options"])} if q.get("options") else None


def insert_for_chapter(db, chapter_id, supp):
    outcome_map = {r.code: r.id for r in db.scalars(
        select(LearningOutcome).where(LearningOutcome.chapter_id == chapter_id)).all()}
    existing = {r.text for r in db.scalars(
        select(Question).where(Question.chapter_id == chapter_id)).all()}
    added = 0
    for q in supp:
        if q["question"] in existing: continue
        oc = q.get("outcome_code")
        db.add(Question(
            chapter_id=chapter_id, topic_id=None,
            outcome_id=outcome_map.get(oc) if oc else None, outcome_code=oc,
            type=QuestionType(q["type"]), difficulty=QuestionDifficulty(q["difficulty"]),
            status=QuestionStatus.APPROVED,
            cognitive_level=BloomLevel(q["cognitive_level"].lower()),
            text=q["question"], options=_options(q), correct_answer=q["answer"],
            explanation=q.get("explanation"), marks=int(q.get("marks", 1)),
            created_by_id=CREATED_BY_ID))
        added += 1
    db.commit()
    return added


# History — needs ~10 more subjective
EXTRA_197 = [
    {"type":"SHORT_ANSWER","outcome_code":"10-CBSE-SOC-HIS-RNE-01","difficulty":"MEDIUM","cognitive_level":"REMEMBER","marks":3,"question":"Who was Frédéric Sorrieu and what were his 1848 prints?","answer":"Frédéric Sorrieu (1807-87) was a French painter who in 1848 prepared a series of FOUR PRINTS visualising his dream of a world made up of 'democratic and social Republics'. The prints showed peoples of Europe and America — men and women of all classes — paying homage to a giant statue of Liberty. They captured the political imagination of nineteenth-century European nationalism: a world of free, self-governing nations united in fraternity.","explanation":"Sorrieu and his prints."},
    {"type":"SHORT_ANSWER","outcome_code":"10-CBSE-SOC-HIS-RNE-03","difficulty":"MEDIUM","cognitive_level":"REMEMBER","marks":3,"question":"What was the Confederation of the Rhine? When was it organised?","answer":"The Confederation of the Rhine was a league of GERMAN STATES created by Napoleon in 1806 after he defeated Austria. It abolished the Holy Roman Empire and consolidated 39 small kingdoms, duchies and principalities into a much smaller number of administratively rationalised states. Within these states Napoleon imposed his Civil Code, abolished feudalism and reformed administration. After Napoleon's fall the Confederation was dissolved at the Congress of Vienna (1815), but its administrative reforms left a lasting impact on the path to German unification.","explanation":"Confederation of the Rhine."},
    {"type":"SHORT_ANSWER","outcome_code":"10-CBSE-SOC-HIS-RNE-04","difficulty":"MEDIUM","cognitive_level":"UNDERSTAND","marks":3,"question":"Who were the Junkers? What role did they play in German nationalism?","answer":"The JUNKERS were the large, conservative, land-owning aristocracy of PRUSSIA — east of the Elbe river. They dominated the Prussian army officer corps and, alongside the King and Bismarck, formed the social backbone of CONSERVATIVE NATIONALISM in Germany. They supported Bismarck's wars of unification (1864/1866/1870-71) and the establishment of the German Empire in 1871. Without their support neither the Prussian army nor the new Empire could have been built. They were thus a key — though deeply conservative — driving force of German national consolidation.","explanation":"Junkers and German nationalism."},
    {"type":"SHORT_ANSWER","outcome_code":"10-CBSE-SOC-HIS-RNE-05","difficulty":"MEDIUM","cognitive_level":"UNDERSTAND","marks":3,"question":"What happened to nationalism in Hungary in 1848?","answer":"In 1848 Hungarians, led by Lajos KOSSUTH, demanded autonomy from the Habsburg Empire and even declared a Hungarian Republic in 1849. The movement was inspired by liberal-nationalist ideals — a Hungarian parliament, Hungarian language, equal civil rights. The Habsburg emperor, with the help of Russian troops, ultimately suppressed the Hungarian revolt by 1849. But the Hungarian challenge forced the Habsburg crown into a series of compromises that culminated in the AUSTRO-HUNGARIAN COMPROMISE of 1867 — granting Hungary effective autonomy as the second half of a 'dual monarchy'. Hungary's 1848 thus failed in the short run but reshaped the empire in the long run.","explanation":"Hungarian 1848."},
    {"type":"SHORT_ANSWER","outcome_code":"10-CBSE-SOC-HIS-RNE-06","difficulty":"MEDIUM","cognitive_level":"UNDERSTAND","marks":3,"question":"What was the Zollverein? How did it help German unification?","answer":"The ZOLLVEREIN — German for 'customs union' — was a customs union among most German states created in 1834 under Prussian leadership. It abolished tariff barriers between member states and allowed free movement of goods. Two effects on unification: (i) ECONOMIC INTEGRATION made German states inter-dependent; cargo, businessmen and workers moved freely, weakening political fragmentation. (ii) Prussia, the largest economic power, became the natural leader of the union — laying the ground for its political leadership later under Bismarck. The Zollverein was thus a quiet but decisive step toward 1871.","explanation":"Zollverein → German unity."},
    {"type":"SHORT_ANSWER","outcome_code":"10-CBSE-SOC-HIS-RNE-06","difficulty":"MEDIUM","cognitive_level":"REMEMBER","marks":3,"question":"How did Garibaldi's march to the south of Italy succeed?","answer":"In May 1860, Giuseppe GARIBALDI sailed from Genoa with about a thousand red-shirted volunteers ('I MILLE') and landed in SICILY. He defeated the Bourbon armies in a series of battles, gathered local peasants disillusioned with the Bourbon kings, and crossed to the mainland. By September 1860 he marched into NAPLES, ending Bourbon rule in southern Italy. Rather than declaring his own kingdom, he handed the conquered territories to King Victor Emmanuel II of Sardinia-Piedmont — the act that made the unification of Italy possible. In March 1861, Victor Emmanuel II was proclaimed KING OF UNITED ITALY.","explanation":"Garibaldi's southern campaign."},
    {"type":"SHORT_ANSWER","outcome_code":"10-CBSE-SOC-HIS-RNE-08","difficulty":"MEDIUM","cognitive_level":"ANALYZE","marks":3,"question":"How was Britannia different from Marianne and Germania, and why?","answer":"BRITANNIA, the female allegory of Britain, was a settled imperial figure: usually crowned, holding a trident and shield, sitting calmly on a rock. She represented an ESTABLISHED, IMPERIAL nation — the world's leading naval and economic power — not a nation struggling to emerge. MARIANNE (France) and GERMANIA (Germany), by contrast, were YOUNG REVOLUTIONARY allegories of nations BEING BORN — Marianne with the red cap of liberty waving the tricolour, Germania with the German sword in hand. The visual difference reflects the historical situation: Britain in the 19th century was ALREADY a unified nation-state, while France and Germany were still working out what their nations should be.","explanation":"Britannia vs Marianne / Germania."},
    {"type":"LONG_ANSWER","outcome_code":"10-CBSE-SOC-HIS-RNE-04","difficulty":"HARD","cognitive_level":"ANALYZE","marks":5,"question":"How did the Romantic movement contribute to nationalist sentiment in 19th-century Europe?","answer":"ROMANTICISM was a cultural and intellectual movement that emerged in the late 18th century and dominated much of the 19th. It REJECTED the Enlightenment's emphasis on cold reason and celebrated EMOTIONS, INTUITION, MYSTICAL FEELINGS, FOLK CULTURE and the SPIRITUAL DIMENSION of human life. Several ways it contributed to nationalism: (i) IT REDEFINED THE NATION — not as a political contract among individuals, but as a SPIRITUAL COMMUNITY (das Volk) sharing language, history, songs and traditions. Johann Gottfried Herder argued that the true 'spirit of the people' was found in folk songs, fairy tales and dances. (ii) IT REVIVED VERNACULAR LANGUAGES AND FOLK CULTURE — the Grimm brothers in Germany collected fairy tales; Polish musicians composed national operas; Italian writers revived their language. (iii) IT GAVE NATIONALISM EMOTIONAL POWER — paintings, music, poetry, novels and plays portrayed national heroes, defeats and dreams in a way that moved ordinary people to action. Beethoven dedicated his Third Symphony to revolutionary France; Verdi's operas became symbols of Italian unification. (iv) IT LINKED LANGUAGE WITH POLITICAL FREEDOM — in partitioned Poland, the use of the Polish language in church services and operas was a form of national resistance. Together with the political programme of the educated middle class (liberty, constitution, equality), the cultural programme of the Romantics gave 19th-century European nationalism BOTH its political demands AND its emotional motive force.","explanation":"Romanticism + nationalism."},
    {"type":"LONG_ANSWER","outcome_code":"10-CBSE-SOC-HIS-RNE-07","difficulty":"HARD","cognitive_level":"EVALUATE","marks":5,"question":"Discuss the formation of the British nation-state. Why is it considered different from the French model?","answer":"Britain's nation-state did NOT emerge from a single revolution. Instead it was the result of a LONG-DRAWN PROCESS in which the English nation steadily extended its dominance over the British Isles. Key milestones: (i) Before the 18th century, the inhabitants of the British Isles had ETHNIC IDENTITIES — English, Welsh, Scot, Irish — not a 'British' identity. (ii) The English parliament, having seized power from the monarchy in 1688 (Glorious Revolution), became the instrument through which a nation-state was built. (iii) ACT OF UNION 1707 between England and Scotland created the 'United Kingdom of Great Britain' — the parliament was henceforth dominated by English members; Scotland's older institutions survived only as junior partners. (iv) IRELAND was forcibly incorporated in 1801. (v) Symbols of the new Britain — the UNION JACK, the national anthem ('God Save Our Noble King'), the English language — were actively PROMOTED, while older Welsh, Scot and Irish identities survived only as subordinate partners. WHY DIFFERENT FROM FRANCE? FRANCE became a nation through SUDDEN REVOLUTION (1789) that overthrew the king and proclaimed sovereignty of the people; the new community of citizens was forged through new institutions, a new flag and a new common language. BRITAIN became a nation through SLOW, ENGLISH-LED INCORPORATION OF ITS ISLAND NEIGHBOURS — through Acts of Union, parliamentary politics and the projection of an English-led 'British' culture. France's nation was built by revolution; Britain's nation was assembled by political and cultural dominance over time.","explanation":"British vs French nation-formation."},
    {"type":"LONG_ANSWER","outcome_code":"10-CBSE-SOC-HIS-RNE-08","difficulty":"HARD","cognitive_level":"ANALYZE","marks":5,"question":"How did female allegories help in transforming nations into 'beings' that citizens could love and serve?","answer":"In the 19th century, ARTISTS, POETS and SCULPTORS PERSONIFIED nations as FEMALE FIGURES — known as ALLEGORIES. Each had specific symbols: MARIANNE, with the red cap of liberty (Phrygian cap), the tricolour and the cockade, embodied LIBERTY and the FRENCH REPUBLIC; her statues stood in public squares and her image appeared on coins and stamps. GERMANIA, with a CROWN OF OAK LEAVES (the German oak symbolised heroism), embodied GERMAN national strength and unity. BRITANNIA, with trident and shield, embodied a settled imperial Britain. Why FEMALE figures? They linked the nation with values considered desirable in 19th-century Europe — beauty, motherhood, courage in defence of children, moral purity, and capacity to evoke love. Several effects: (i) the nation became a BEING that citizens could love — like a mother — not just an abstract idea. (ii) Patriotism became EMOTIONALLY POWERFUL — soldiers fought for 'la patrie', for 'die Mutter Heimat'. (iii) Public spaces (squares, monuments, school halls) became filled with these symbols — making nationalism visible in everyday life. (iv) Currency, stamps and official documents carried these images — reinforcing national identity in mundane transactions. (v) Women were paradoxically EXCLUDED from political rights even as they were embraced as symbols of the nation; the fight for women's suffrage was a long parallel struggle in the 19th and 20th centuries. The female allegory was thus a powerful tool of nation-building — but it also reflected the contradictions of an age that loved 'Mother Nation' while denying daughters and wives the vote.","explanation":"Female allegory function in detail."},
]

# Geography — needs ~12 more subjective
EXTRA_202 = [
    {"type":"SHORT_ANSWER","outcome_code":"10-CBSE-SOC-GEO-RD-01","difficulty":"MEDIUM","cognitive_level":"ANALYZE","marks":3,"question":"Explain why even the same physical thing can be a resource in one place and not in another, with two examples.","answer":"Because resources are products of NATURE × TECHNOLOGY × INSTITUTIONS, the same physical thing can be a resource in one society and not in another. EXAMPLE 1 — DEEP-SEA OIL is a major resource for countries like Norway and Saudi Arabia, which have the technology and capital to drill; for a poor nation without that capacity, the oil is just rock-bound stock. EXAMPLE 2 — PINE FORESTS are revered as sacred groves in some adivasi areas of India and protected from cutting; in another society the same forest is a timber resource. EXAMPLE 3 — NATURAL GAS reserves became 'resources' for many countries only after fracking technology emerged in the 2000s. So the very status of a thing as a 'resource' depends on technology, economics and culture.","explanation":"Resource = social construction."},
    {"type":"SHORT_ANSWER","outcome_code":"10-CBSE-SOC-GEO-RD-03","difficulty":"MEDIUM","cognitive_level":"REMEMBER","marks":3,"question":"What were the three main outcomes of the Rio Earth Summit (1992)?","answer":"More than 100 heads of state met in Rio de Janeiro in June 1992 to address environmental and development concerns. Three major outcomes: (i) DECLARATION ON CLIMATE CHANGE — laying foundations for the later Kyoto and Paris agreements. (ii) CONVENTION ON BIOLOGICAL DIVERSITY (CBD) — to conserve biological diversity, ensure sustainable use and equitable benefit-sharing. (iii) AGENDA 21 — a global plan of action for sustainable development; every local government to draw its own LOCAL AGENDA 21. The Summit signalled a global commitment to combine economic development with environmental protection.","explanation":"Three outcomes of Rio."},
    {"type":"SHORT_ANSWER","outcome_code":"10-CBSE-SOC-GEO-RD-04","difficulty":"MEDIUM","cognitive_level":"ANALYZE","marks":3,"question":"Why is mineral wealth alone not enough for the prosperity of a state? Cite Indian examples.","answer":"States like Jharkhand, Chhattisgarh, Odisha and parts of Madhya Pradesh are RICH in coal, iron ore, bauxite and other minerals. Yet many of their districts have HIGH POVERTY rates. Mineral wealth without good resource planning can lead to: (i) ENVIRONMENTAL DEGRADATION — mining without restoration; deforestation; water pollution. (ii) WEAK LOCAL BENEFITS — minerals are extracted and exported elsewhere; royalties and jobs do not always reach local people. (iii) DISPLACEMENT of local communities (often adivasi) without proper rehabilitation. (iv) NEGLECT of agriculture, education and health. So a state must have not only resources but also INSTITUTIONS for fair distribution, environmental protection and skill development. Resource planning + Local Agenda 21 are designed to address this.","explanation":"Resource curse + planning."},
    {"type":"SHORT_ANSWER","outcome_code":"10-CBSE-SOC-GEO-RD-05","difficulty":"MEDIUM","cognitive_level":"UNDERSTAND","marks":3,"question":"Why is land considered the most basic resource for human civilisation?","answer":"Land is the BASIS for almost all human activity. (i) AGRICULTURE — about 60% of Indians depend on land for food and livelihood. (ii) HOUSING and INFRASTRUCTURE — every house, road, school, factory needs land. (iii) NATURAL VEGETATION and WILDLIFE depend on land. (iv) Land supports ECONOMIC activities including industry, mining and tourism, and is the medium for TRANSPORT and COMMUNICATION. (v) Land carries the MINERAL WEALTH below it. (vi) Land has CULTURAL and SPIRITUAL value for communities — adivasi tribes call themselves children of the soil. Without land, none of the higher economic activities is possible. Yet land is FINITE — therefore careful planning of its use is one of the most important issues in any country.","explanation":"Land as basic resource."},
    {"type":"SHORT_ANSWER","outcome_code":"10-CBSE-SOC-GEO-RD-06","difficulty":"MEDIUM","cognitive_level":"APPLY","marks":3,"question":"Suggest five ways to combat land degradation in mining-affected regions.","answer":"(i) FILL AND RESTORE the open mining pits after extraction is complete; convert them into ponds or plantations. (ii) AFFORESTATION on mined hills — planting native species suited to the soil and climate. (iii) Treat and DISPOSE INDUSTRIAL EFFLUENTS properly so they do not pollute land or water. (iv) STRICT REGULATION of mining licences; mining only after environmental impact assessment; involve local communities. (v) BIOLOGICAL RECLAMATION — using grasses and shrubs that improve soil quality. (vi) Restoration of FOREST cover and protection of wildlife corridors. (vii) JOINT FOREST MANAGEMENT with adivasi communities under the Forest Rights Act. Together, these steps can restore degraded mined land over time.","explanation":"Five+ remedies."},
    {"type":"SHORT_ANSWER","outcome_code":"10-CBSE-SOC-GEO-RD-07","difficulty":"MEDIUM","cognitive_level":"REMEMBER","marks":3,"question":"What is the difference between Khadar and Bangar alluvial soils?","answer":"Both are types of ALLUVIAL soil found in the northern plains of India, but: KHADAR is the YOUNGER alluvium, deposited by river floods every year. It has finer particles, more humus and is more FERTILE. It is the soil of the Bhabar / Tarai and floodplains. BANGAR is the OLDER alluvium, lying away from active flood-plains. It is older, slightly coarser, has more KANKAR (lime nodules) in the lower horizons and is somewhat less fertile than Khadar. Khadar is renewed every year while Bangar is essentially fixed.","explanation":"Khadar vs Bangar."},
    {"type":"SHORT_ANSWER","outcome_code":"10-CBSE-SOC-GEO-RD-07","difficulty":"MEDIUM","cognitive_level":"ANALYZE","marks":3,"question":"Why does black soil develop deep cracks during the hot weather, and how is this useful?","answer":"Black soils contain a high proportion of CLAY (extremely fine particles) which holds water. During the cold and wet seasons the soil is moist and SWELLS. In the HOT, DRY months, water EVAPORATES from the soil and the clay particles SHRINK, opening up DEEP CRACKS on the surface. These cracks are useful in two ways: (i) they help in PROPER AERATION of the soil — air reaches deep layers, important for root and microbial activity. (ii) When the next rains come, water soaks deep into the cracks, recharging the soil profile. Farmers traditionally TILL black soil immediately after the first showers — when it is still soft but not yet sticky.","explanation":"Black soil cracks."},
    {"type":"SHORT_ANSWER","outcome_code":"10-CBSE-SOC-GEO-RD-07","difficulty":"MEDIUM","cognitive_level":"ANALYZE","marks":3,"question":"Why are arid soils naturally low in humus? How can they still be made productive?","answer":"In arid regions of western Rajasthan and adjacent areas, low rainfall and very high day-time temperatures result in: (i) SCANT vegetation and therefore LITTLE organic matter falling to the ground; (ii) HIGH evaporation that quickly removes any moisture; (iii) high temperatures that destroy soil micro-organisms; (iv) lower-soil layers full of KANKAR (lime nodules) that block water infiltration. As a result, humus is naturally low. With careful management, however, these soils can be made productive: PROPER IRRIGATION (with the Indira Gandhi Canal in western Rajasthan, large areas have been brought under cultivation), addition of MANURES and ORGANIC MATTER, growing of DROUGHT-RESISTANT crops like millets and gram, and SOIL CONSERVATION measures like shelter belts.","explanation":"Why low humus + remedies."},
    {"type":"SHORT_ANSWER","outcome_code":"10-CBSE-SOC-GEO-RD-08","difficulty":"MEDIUM","cognitive_level":"REMEMBER","marks":3,"question":"What is wind erosion? In which Indian regions is it most severe?","answer":"WIND EROSION is the removal of loose, dry topsoil from flat or gently sloping land by strong WINDS. It is most severe in REGIONS WITH LOW VEGETATION and SANDY soils — chiefly the Thar desert and adjacent western Rajasthan, the Rann of Kutch in Gujarat, and parts of the Punjab plains. Causes include over-grazing, deforestation and dry-fallow cultivation. Effects: loss of fertile topsoil, encroachment of sand dunes onto fields, and reduction in agricultural productivity. Conservation: planting SHELTER BELTS (rows of trees along field edges), stabilising sand dunes with thorny bushes, and reviving vegetation cover have helped significantly in western Rajasthan.","explanation":"Wind erosion + Indian regions."},
    {"type":"LONG_ANSWER","outcome_code":"10-CBSE-SOC-GEO-RD-04","difficulty":"HARD","cognitive_level":"APPLY","marks":5,"question":"You are asked to plan resource use for a coastal Indian state. Suggest a five-point plan that balances development with sustainability.","answer":"For a coastal Indian state — say Kerala or Gujarat — I would propose: (1) MAP RESOURCES carefully — coastal land use, fisheries, tourism potential, mineral sands, fresh-water aquifers, mangroves and biodiversity hotspots. Make a detailed inventory. (2) PROTECT MANGROVES AND COASTAL ECOSYSTEMS that prevent erosion, host fisheries and absorb carbon. Stop further encroachment by industry and aquaculture. (3) SUSTAINABLE FISHERIES — enforce closed-season rules, regulate trawler size, ban destructive trawling near reefs; support traditional fisher livelihoods with insurance, cold storage and minimum-price arrangements. (4) MIXED INDUSTRY-AGRICULTURE-TOURISM ECONOMY — diversify so the state does not depend on any one resource; promote eco-tourism, organic spice farming, fisheries-based food industry, IT and skill-based service sectors. (5) RAINWATER HARVESTING + WATER MANAGEMENT — store monsoon water in tanks; recharge aquifers; control over-pumping that causes saline-water intrusion. (6) DISASTER PREPAREDNESS — early-warning systems for cyclones, mangrove buffer zones, climate-resilient coastal infrastructure. (7) JOINT-MANAGEMENT institutions with PANCHAYATS — ensure fishermen, farmers and women are part of decision-making. The plan balances DEVELOPMENT (jobs, income, infrastructure) with SUSTAINABILITY (ecosystems, water, climate resilience), drawing on the Resource Planning framework, Agenda 21 and Indian state experience.","explanation":"Coastal state plan."},
    {"type":"LONG_ANSWER","outcome_code":"10-CBSE-SOC-GEO-RD-07","difficulty":"HARD","cognitive_level":"ANALYZE","marks":5,"question":"Explain how parent rock, climate, vegetation and time interact to form different soil types in India.","answer":"Soil takes MILLIONS of years to form even a few centimetres of depth. Five factors interact in its formation: PARENT ROCK supplies the mineral content. CLIMATE controls weathering, leaching, water retention and microbial activity. RELIEF determines drainage and erosion. VEGETATION supplies humus and protects from erosion. TIME allows the soil profile to develop. Examples in India: (i) ALLUVIAL — the parent material is sediment carried by Himalayan and peninsular RIVERS over time; the gentle slope of the plains traps these sediments; the moderate climate aids fertility. (ii) BLACK / REGUR — parent material is BASALT (volcanic lava); the dry-and-wet climate of the Deccan plateau allows clay-mineral formation; intense weathering produces a clayey, moisture-holding soil rich in calcium, potash, lime. (iii) RED & YELLOW — parent rock is CRYSTALLINE IGNEOUS ROCK; low rainfall keeps the soil in place; iron oxide gives the red colour. (iv) LATERITE — parent rocks of the Western Ghats and Eastern Ghats; under HIGH RAIN + HEAT, intense leaching washes away lime and silica leaving a residual iron-and-aluminium soil. (v) ARID — parent rock plus dry climate plus minimal vegetation produce sandy, saline soils with kankar layers. (vi) FOREST — hilly slopes plus wet climate plus thick vegetation produce loamy, humus-rich (in lower areas) and acidic (on high slopes) soils. So India's wide variety of soils mirrors its variety of parent rocks, climates, slopes and vegetation — a geographical mosaic.","explanation":"Soil formation factors."},
    {"type":"LONG_ANSWER","outcome_code":"10-CBSE-SOC-GEO-RD-08","difficulty":"HARD","cognitive_level":"EVALUATE","marks":5,"question":"Why is soil conservation critical for India's future? Discuss with three regional examples.","answer":"India loses MILLIONS of tonnes of topsoil every year to erosion and degradation — and topsoil takes centuries to form. Soil conservation is therefore CRITICAL for: (i) FOOD SECURITY of 1.4 billion people; (ii) RURAL LIVELIHOODS that depend on agriculture and animal husbandry; (iii) WATER security (degraded land cannot retain water); (iv) BIODIVERSITY conservation; (v) CLIMATE RESILIENCE (healthy soils store carbon). REGIONAL EXAMPLES: (a) THE HIMALAYAS — steep slopes, heavy monsoon rain, deforestation and over-grazing have caused severe erosion; remedy = TERRACE cultivation and afforestation that have helped in Himachal Pradesh and Uttarakhand. (b) THE CHAMBAL BASIN (MP, Rajasthan, UP) — gully erosion has created vast 'bad lands' / RAVINES; remedy = check dams, contour bunds, shelter belts, and reclamation projects. (c) WESTERN RAJASTHAN — wind erosion, sand-dune migration; remedy = SHELTER BELTS of trees, stabilisation of dunes with thorny bushes; the Indira Gandhi Canal has also brought irrigation. (d) PUNJAB / HARYANA — over-irrigation has caused water-logging and salinity; remedy = drip irrigation, salt-tolerant crops, drainage. Each region needs its own conservation mix. Without a nationwide effort, India risks losing fertility, biodiversity and water — the very resources future generations will need most.","explanation":"Soil conservation national + regional."},
]

