    {"type":"MCQ","outcome_code":"10-CBSE-SOC-CIV-PS-01","difficulty":"EASY","cognitive_level":"REMEMBER","marks":1,"question":"Which language is spoken by 1% of Belgians?","options":["Dutch","French","German","English"],"answer":"German","explanation":"Small German-speaking minority."},
